modern_c2_q7.program:
def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    vehicle_patches = image_patch.find("vehicle")
    red_vehicle_patches = [v for v in vehicle_patches if v.verify_property("vehicle", "red")]

    if not red_vehicle_patches:
        return image_patch

    number_patches = image_patch.find("number")
    number_9_patches = [n for n in number_patches if n.text == "9"]

    if not number_9_patches:
        return red_vehicle_patches[0]

    max_overlap = -1
    best_vehicle = red_vehicle_patches[0]

    for vehicle in red_vehicle_patches:
        for number in number_9_patches:
            if vehicle.overlaps_with(number.left, number.lower, number.right, number.upper):
                overlap = min(vehicle.width, number.width) * min(vehicle.height, number.height)
                if overlap > max_overlap:
                    max_overlap = overlap
                    best_vehicle = vehicle

    return best_vehicle

